'use strict';

// MODULES //

var repeat = require( '@stdlib/string/repeat' );
var rtrim = require( '@stdlib/string/right-trim' );
var ltrim = require( '@stdlib/string/left-trim' );
var wrap = require( '@stdlib/_tools/repl-txt/wrap-text' );
var unwrap = require( './unwrap.js' );


// VARIABLES //

var MAX_WIDTH = 80;
var DESC_INDENT = 4;
var TAG_INDENT = 8;
var TAG_PREFIX = repeat( ' ', TAG_INDENT );
var DESC_OPTS = {
	'indent': DESC_INDENT,
	'maxWidth': MAX_WIDTH
};
var TAG_OPTS = {
	'indent': TAG_INDENT,
	'maxWidth': MAX_WIDTH
};


// FUNCTIONS //

/**
* Finds the first premature wrap by comparing original lines against rewrapped lines.
*
* @private
* @param {Array<string>} olines - original lines
* @param {Array<string>} rlines - rewrapped lines
* @returns {(Object|null)} object with `idx` and `extra` properties, or null
*/
function findPrematureWrap( olines, rlines ) {
	var extra;
	var i;

	for ( i = 0; i < olines.length; i++ ) {
		if ( olines[ i ] !== rlines[ i ] ) {
			if ( rlines[ i ] && rlines[ i ].length > olines[ i ].length ) {
				extra = ltrim( rlines[ i ].substring( olines[ i ].length ) );
				if ( extra ) {
					return {
						'idx': i,
						'extra': extra
					};
				}
			}
			return null;
		}
	}
	return null;
}

/**
* Finds the line number where a tag description begins within a section.
*
* @private
* @param {Object} section - section node
* @param {Object} tag - tag object
* @returns {NonNegativeInteger} line number of the tag description start
*/
function findTagDescriptionLine( section, tag ) {
	var firstLine;
	var content;
	var idx;

	content = section.content;
	firstLine = tag.description.split( '\n' )[ 0 ];
	idx = content.indexOf( TAG_PREFIX + firstLine );
	if ( idx < 0 ) {
		return section.start;
	}
	return section.start + 2 + content.substring( 0, idx ).split( '\n' ).length;
}


// MAIN //

/**
* Rule for detecting premature line wrapping in the `repl.txt` files.
*
* @param {Context} context - lint context
* @returns {Object} validators
*/
function main( context ) {
	/**
	* Checks whether a description has premature line wrapping.
	*
	* @private
	* @param {Object} description - description node
	*/
	function checkDescription( description ) {
		var unwrapped;
		var rewrapped;
		var result;
		var line;
		var raw;

		raw = rtrim( description.raw );
		unwrapped = unwrap( raw, DESC_INDENT );
		rewrapped = wrap( unwrapped, DESC_OPTS );
		if ( rewrapped === raw ) {
			return;
		}
		result = findPrematureWrap( raw.split( '\n' ), rewrapped.split( '\n' ) );
		if ( result ) {
			line = description.start + result.idx + 1;
			context.report( '"' + result.extra + '" can fit on the previous line', {
				'start': line,
				'end': line
			});
		}
	}

	/**
	* Checks whether tag descriptions have premature line wrapping.
	*
	* @private
	* @param {Object} section - parameters or returns section
	* @param {string} label - section label
	*/
	function checkTags( section, label ) {
		var rewrappedLines;
		var unwrapped;
		var rewrapped;
		var baseLine;
		var olines;
		var result;
		var tags;
		var line;
		var i;

		tags = section.tags;
		if ( !tags ) {
			return;
		}
		for ( i = 0; i < tags.length; i++ ) {
			unwrapped = unwrap( TAG_PREFIX + tags[ i ].description, TAG_INDENT );
			rewrapped = wrap( unwrapped, TAG_OPTS );
			rewrappedLines = rewrapped.split( '\n' );
			rewrappedLines[ 0 ] = rewrappedLines[ 0 ].substring( TAG_OPTS.indent ); // eslint-disable-line max-len
			olines = tags[ i ].description.split( '\n' );
			result = findPrematureWrap( olines, rewrappedLines );
			if ( result ) {
				baseLine = findTagDescriptionLine( section, tags[ i ] );
				line = baseLine + result.idx + 1;
				context.report( 'In ' + label + ' "' + tags[ i ].name + '", "' + result.extra + '" can fit on the previous line', {
					'start': line,
					'end': line
				});
			}
		}
	}

	/**
	* Checks whether parameter tag descriptions have premature line wrapping.
	*
	* @private
	* @param {Object} section - parameters section
	*/
	function checkParameters( section ) {
		checkTags( section, 'parameter' );
	}

	/**
	* Checks whether return tag descriptions have premature line wrapping.
	*
	* @private
	* @param {Object} section - returns section
	*/
	function checkReturns( section ) {
		checkTags( section, 'return' );
	}

	return {
		'description': checkDescription,
		'parameters': checkParameters,
		'returns': checkReturns
	};
}


// EXPORTS //

module.exports = main;
